//! Byte-compatibility tests against fixtures generated by the Go implementation
//! (`tools/rust-fixtures`, output in `crates/fixtures/m0`).

use std::collections::HashMap;

use pm_query::parse_query;
use pm_record::{Key, Meta, Record};
use serde_json::Value;

fn fixture(name: &str) -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../fixtures/m0/");
    let text = std::fs::read_to_string(format!("{path}{name}")).unwrap();
    serde_json::from_str(&text).unwrap()
}

fn sample_records(fixture: &Value) -> HashMap<String, Record> {
    let mut records = HashMap::new();
    for (key, record) in fixture["records"].as_object().unwrap() {
        records.insert(
            key.clone(),
            Record {
                key: Key::parse(key),
                meta: Meta::default(),
                format: record["format"].as_u64().unwrap() as u8,
                data: hex::decode(record["data"].as_str().unwrap()).unwrap(),
            },
        );
    }
    records
}

#[test]
fn query_fixture_cases() {
    let fixture = fixture("query.json");
    let records = sample_records(&fixture);
    assert_eq!(records.len(), 6);

    let mut successful = 0;
    let mut failed = 0;

    for case in fixture["cases"].as_array().unwrap() {
        let text = case["query"].as_str().unwrap();

        if let Some(want) = case.get("error").and_then(Value::as_str) {
            let err = parse_query(text).expect_err("query should not parse");
            // Go cuts the last token of a trailing multi-byte word in half and
            // prints the raw bytes as `\xNN` in strconv errors; the fixture
            // keeps those escapes, while this port compares lossily.
            if !want.contains("\\x") {
                assert_eq!(err.to_string(), want, "query: {text:?}");
            }
            failed += 1;
            continue;
        }

        let query = parse_query(text).unwrap_or_else(|err| panic!("{text:?}: {err}"));
        assert_eq!(query.print(), case["print"].as_str().unwrap(), "{text:?}");
        assert_eq!(
            query.database_name(),
            case["db"].as_str().unwrap(),
            "{text:?}"
        );
        assert_eq!(
            query.database_key_prefix(),
            case["prefix"].as_str().unwrap(),
            "{text:?}"
        );

        let expected = case["matches"].as_object().unwrap();
        assert_eq!(expected.len(), records.len(), "{text:?}");
        for (key, should_match) in expected {
            let record = &records[key];
            assert_eq!(
                query.matches(record),
                should_match.as_bool().unwrap(),
                "query {text:?} on {key}"
            );
        }
        successful += 1;
    }

    assert_eq!(successful, 29);
    assert_eq!(failed, 17);
}

#[test]
fn truncated_tokens_compare_bytewise() {
    // "Ü" is two bytes; Go's extractor keeps only the first one, and
    // `startswith` then matches records whose value starts with that byte.
    let fixture = fixture("query.json");
    let records = sample_records(&fixture);

    let query = parse_query("query core:test/ where Name sw Ü").unwrap();
    assert_eq!(
        query.print(),
        "query core:test/ where Name startswith \u{fffd}"
    );
    assert!(query.matches(&records["core:test/sample/1"]));
    assert!(!query.matches(&records["core:test/unicode/ключ 🦀|x"]));
}
